/* HLS.js loader for old Chromium/WebDisplays.
   Loads the pinned hls.js 0.14.17 UMD build from cdnjs.
   For fully offline/local hosting, replace this loader with the official hls.min.js distribution file. */
(function () {
  var script = document.createElement('script');
  script.src = 'https://cdnjs.cloudflare.com/ajax/libs/hls.js/0.14.17/hls.min.js';
  script.async = true;
  script.onload = function () {
    if (window.__onHlsLoaded) window.__onHlsLoaded();
  };
  script.onerror = function () {
    window.__hlsLoadFailed = true;
    if (window.__onHlsLoadFailed) window.__onHlsLoadFailed();
  };
  (document.head || document.getElementsByTagName('head')[0] || document.documentElement).appendChild(script);
}());